<?php include 'config.php'; $msg=''; if(isset($_GET['delete'])) mysqli_query($conn,'DELETE FROM tasks WHERE id='.(int)$_GET['delete']); if(isset($_GET['complete'])) mysqli_query($conn,"UPDATE tasks SET status='Completed' WHERE id=".(int)$_GET['complete']);
if($_SERVER['REQUEST_METHOD']=='POST'){ $name=trim($_POST['task_name']); $desc=trim($_POST['description']); $date=$_POST['due_date']; if($name==''||$desc==''||$date<=date('Y-m-d')){$msg='Due date must be in future and fields cannot be empty';} else {$stmt=mysqli_prepare($conn,'INSERT INTO tasks(task_name,description,due_date) VALUES(?,?,?)'); mysqli_stmt_bind_param($stmt,'sss',$name,$desc,$date); mysqli_stmt_execute($stmt);}}
$pending=mysqli_query($conn,"SELECT * FROM tasks WHERE status='Pending' ORDER BY due_date"); $done=mysqli_query($conn,"SELECT * FROM tasks WHERE status='Completed' ORDER BY due_date"); ?>
<!DOCTYPE html><html><head><title>Q13 Task Manager</title><link rel="stylesheet" href="style.css"></head><body><div class="container"><h1>Task Manager</h1><p class="error"><?php echo $msg; ?></p><form method="post"><input name="task_name" placeholder="Task Name"><textarea name="description" placeholder="Description"></textarea><input type="date" name="due_date"><button>Add Task</button></form><h2>Pending Tasks</h2><?php while($r=mysqli_fetch_assoc($pending)){ ?><div class="card"><b><?php echo $r['task_name']; ?></b><p><?php echo $r['description']; ?></p><p>Due: <?php echo $r['due_date']; ?></p><a href="?complete=<?php echo $r['id']; ?>">Mark Complete</a> | <a onclick="return confirmDelete()" href="?delete=<?php echo $r['id']; ?>">Delete</a></div><?php } ?><h2>Completed Tasks</h2><?php while($r=mysqli_fetch_assoc($done)){ ?><div class="card"><b><?php echo $r['task_name']; ?></b> - Completed <a onclick="return confirmDelete()" href="?delete=<?php echo $r['id']; ?>">Delete</a></div><?php } ?></div><script src="script.js"></script></body></html>
